                                                 "(%u).",
                                                 K_msbs, band->numbps);
                                         headerError_ = true;
                                         throw CorruptPacketHeaderException();
                                  }
                                  else
                                  {
                                         cblk->numbps = band->numbps - K_msbs;
                                  }
                                  if(cblk->numbps > maxBitPlanesGRK)
                                  {
                                         Logger::logger_.warn("Number of bit planes %u is larger than maximum %u",
